local o={}
for _,n in pairs({'cryogenic-plant','chemical-plant','pumpjack','offshore-pump','storage-tank','rocket-silo'}) do local p=prototypes.entity[n] local cb=p.collision_box o[#o+1]=n..' box '..cb.left_top.x..','..cb.left_top.y..' '..cb.right_bottom.x..','..cb.right_bottom.y
for i,fb in pairs(p.fluidbox_prototypes) do local t={} for _,pc in pairs(fb.pipe_connections) do local ps={} for _,q in pairs(pc.positions) do ps[#ps+1]='('..q.x..','..q.y..')' end t[#t+1]=pc.flow_direction..' dir'..tostring(pc.direction)..' '..table.concat(ps,'') end o[#o+1]='  fb'..i..' '..fb.production_type..' '..table.concat(t,' ; ') end end
for _,n in pairs({'ammonia-rocket-fuel','rocket-part','rocket-fuel','fluoroketone-cold-barrel','empty-fluoroketone-cold-barrel'}) do local r=prototypes.recipe[n] if r then local a={} for _,i in pairs(r.ingredients) do a[#a+1]=i.amount..' '..i.name end local b={} for _,p in pairs(r.products) do b[#b+1]=(p.amount or '?')..' '..p.name end o[#o+1]=n..' '..r.energy..'s: '..table.concat(a,', ')..' -> '..table.concat(b,', ')..' enabled='..tostring(game.forces.player.recipes[n].enabled) end end
local it=prototypes.item['cryogenic-science-pack'] o[#o+1]='pack weight '..it.weight..' stack '..it.stack_size
o[#o+1]='foundation tech units '..game.forces.player.technologies['foundation'].research_unit_count
local f=game.forces.player for _,n in pairs({'foundation','quantum-processor','railgun','fusion-reactor','fluid-handling','rocket-silo','logistic-system','automation-3'}) do local te=f.technologies[n] local pr={} for k,_ in pairs(te.prerequisites) do pr[#pr+1]=k..(f.technologies[k].researched and '+' or '-') end o[#o+1]=n..' researched='..tostring(te.researched)..' units '..te.research_unit_count..' prereq '..table.concat(pr,',') end
local n=0 local names={} for k,te in pairs(f.technologies) do if not te.researched and te.enabled then for _,ing in pairs(te.research_unit_ingredients) do if ing.name=='cryogenic-science-pack' then n=n+1 names[#names+1]=k..':'..te.research_unit_count break end end end end o[#o+1]='techs needing cryo '..n..': '..table.concat(names,' ')
rcon.print(table.concat(o,'\n'))
